<?php
namespace Tests\Feature;
use App\Models\Employee; use App\Models\Shift; use App\Models\Tenant; use App\Services\AttendanceService; use Carbon\Carbon; use Illuminate\Support\Str; use Tests\TestCase;
class AttendanceServiceTest extends TestCase { public function test_shift_punches_compute_work_late_and_early_minutes():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Attendance '.Str::random(4)]);try{tenancy()->initialize($tenant);$e=Employee::create(['name'=>'E','national_id'=>'AT-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active']);$shift=Shift::create(['code'=>'D1','name'=>'Day','start_time'=>'09:00','end_time'=>'17:00','break_minutes'=>60,'grace_minutes'=>5]);$s=app(AttendanceService::class);$s->assignShift($e,$shift,Carbon::parse('2026-09-01'));$s->recordPunch($e,'in',Carbon::parse('2026-09-05 09:10'),'manual');$a=$s->recordPunch($e,'out',Carbon::parse('2026-09-05 16:50'),'manual');$this->assertSame(400,$a->worked_minutes);$this->assertSame(10,$a->late_minutes);$this->assertSame(10,$a->early_leave_minutes);$this->assertSame('exception',$a->status);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
